def max_juice_drunk(n, actions):
    def is_same_moves(prev_moves):
        return len(set(prev_moves)) == 1

    juice_count = 0
    prev_moves = []

    for i in range(len(actions)):
        current_person = i % n
        if current_person == 0:
            continue

        if i >= 3:
            prev_moves.append(actions[i - 3])

        if len(prev_moves) == 3 and is_same_moves(prev_moves):
            juice_count += 1
            prev_moves = []

    return juice_count

