def max_juice_drunk(n, game_actions):
    vasya_moves = []
    juice_count = 0

    for i, action in enumerate(game_actions):
        current_person = i % n
        if current_person == 0:
            vasya_moves.append(action)
            if len(vasya_moves) >= 4:
                if vasya_moves[-1] == vasya_moves[-2] == vasya_moves[-3] == vasya_moves[-4]:
                    juice_count += 1
                    vasya_moves.pop(0)  # Remove the oldest move to maintain the window of 4 moves

    return juice_count

if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    game_actions = data[1]
    print(max_juice_drunk(n, game_actions))
